module dsfd_xstg_515 (
    input wire [0:0] ck,
    input wire [0:0] cw,
    input wire [514:0] i,
    output wire [514:0] o
);
    // SEL_XSTG crossing stage (S81-RERUN v8): the end block (its own clock region, cw) -> band block (ck)
    // crossing is bounded at 382-385 ps, beyond a single-register window (data changes every cycle), so
    // it crosses through the d8g1 meso FIFO (the closed die crossing: arcs settle in 1.5 T - 60 ps, low
    // guard flop at 1.5 T) with registered pins.  Lane vr: i[0] rst_n, i[1] valid.
    reg [1:0] rsync_q; always @(posedge ck[0] or negedge i[0]) if (!i[0]) rsync_q <= 2'b00; else rsync_q <= {rsync_q[0], 1'b1};
    wire rsync = rsync_q[1];
    reg [514:0] ir; always @(posedge cw[0]) ir <= i;
    wire rv, wl, rl, wf, rf_, wr; wire [512:0] rq;
    ot_meso_fifo #(.W(513), .ENABLE(1'b1), .DEPTH(8), .OFFSET(4), .GUARD_LO(1), .GUARD_HI(7), .CREDITS(16)) u_x (.wclk(cw[0]), .wrst_n(ir[0]), .w_v(ir[1]), .w_rdy(wr), .w_d(ir[514:2]), .rclk(ck[0]), .rrst_n(rsync), .r_v(rv), .r_rdy(1'b1), .r_d(rq), .w_live(wl), .r_live(rl), .w_fault(wf), .r_fault(rf_));
    reg [514:0] orr; always @(posedge ck[0]) orr <= {rq, rv & rl, rsync};
    assign o = orr;
endmodule
